# ─── Helper Functions ───────────────────────────────────────────────────

def glob_to_regex(glob_pattern: str) -> str:
    """
    Convert a glob pattern to a regex pattern.
    Supports **, *, ?, and character classes.
    """
    regex = re.escape(glob_pattern)
    # Convert ** to match any characters including slashes
    regex = regex.replace(r"\*\*", ".*")
    # Convert * to match any characters except slashes
    regex = regex.replace(r"\*", "[^/]*")
    # Convert ? to match any single character except slash
    regex = regex.replace(r"\?", "[^/]")
    # Convert (x|y) groups (already escaped, so handle manually)
    regex = regex.replace(r"\(x\)", "(x)").replace(r"\|", "|")
    return f"^{regex}$"


